* { margin: 0; padding: 0; box-sizing: border-box; }
body { font-family: 'Sarabun', sans-serif; background: #f4f4f4; overflow-x: hidden; }
.hidden { display: none !important; }

/* Animation เลื่อนขึ้น */
@keyframes fadeInUp {
    from { opacity: 0; transform: translateY(40px); }
    to { opacity: 1; transform: translateY(0); }
}
.animate-up { animation: fadeInUp 1s ease-out forwards; }

/* Hero Section */
.hero-section {
    height: 100vh; display: flex; align-items: center; justify-content: center;
    position: relative; color: white; text-align: center; background: #000;
}
.hero-bg {
    position: absolute; top:0; left:0; width:100%; height:100%;
    background: linear-gradient(rgba(0,0,0,0.6), rgba(0,0,0,0.6)), 
                url('https://images.unsplash.com/photo-1589829545856-d10d557cf95f?q=80&w=2000') center/cover no-repeat fixed;
    z-index: 1;
}
.hero-text { z-index: 2; padding: 20px; }
.hero-text h1 { font-family: 'Kanit'; font-size: 3.5rem; }

/* หน้าพื้นขาว */
.white-content { background: white; padding: 80px 20px; position: relative; z-index: 5; margin-top: -50px; border-radius: 40px 40px 0 0; }
.container { max-width: 1000px; margin: auto; }
.info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 40px; }
.info-card { background: #f9f9f9; padding: 25px; border-radius: 15px; border-left: 5px solid #d4af37; }

.card-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px; }
.law-card { background: #2c3e50; color: white; padding: 30px; border-radius: 20px; text-align: center; cursor: pointer; transition: 0.3s; font-family: 'Kanit'; }
.law-card:hover { background: #d4af37; transform: translateY(-10px); }

/* Overlay & Quiz */
.overlay { position: fixed; top:0; left:0; width:100%; height:100%; z-index: 1000; display: flex; align-items: center; justify-content: center; background: rgba(0,0,0,0.85); }

/* 🛠 แก้ไขรูปทนาย Phoenix/Edgeworth */
#quiz-screen {
    /* ใช้สีพื้นหลังสีน้ำเงินเข้มสำรองไว้ */
    background: linear-gradient(rgba(0,0,50,0.8), rgba(0,0,0,0.9)), 
                url('https://img5.pic.in.th/file/secure-sv1/phoenix-blue.png') center/cover no-repeat;
}

#result-screen.bg-win {
    background: linear-gradient(rgba(0,50,0,0.8), rgba(0,0,0,0.9)), 
                url('https://img5.pic.in.th/file/secure-sv1/phoenix-blue.png') center/cover no-repeat !important;
}

#result-screen.bg-lose {
    background: linear-gradient(rgba(50,0,0,0.8), rgba(0,0,0,0.9)), 
                url('https://img5.pic.in.th/file/secure-sv1/miles-red.png') center/cover no-repeat !important;
}

.modal-box, .quiz-box, .result-box { background: rgba(255,255,255,0.95); padding: 40px; border-radius: 25px; width: 90%; max-width: 600px; text-align: center; }
.scroll-area { max-height: 350px; overflow-y: auto; text-align: left; margin: 20px 0; padding-right: 10px; line-height: 1.8; }

#q-options { display: flex; flex-direction: column; gap: 12px; margin-top: 20px; }
.opt-btn { padding: 15px; border: 2px solid #d4af37; border-radius: 12px; background: white; cursor: pointer; font-size: 1rem; transition: 0.2s; }
.opt-btn:hover { background: #d4af37; color: white; }

.btn-go { background: #d4af37; color: white; border: none; padding: 15px 30px; border-radius: 10px; cursor: pointer; font-weight: bold; font-size: 1.1rem; }
.btn-back { background: #eee; border: none; padding: 15px 30px; border-radius: 10px; cursor: pointer; margin-right: 10px; }

/* 2. รูปทนายตอนทำแบบทดสอบ (Quiz Background) */
#quiz-screen {
    /* ใส่รหัสรูปทนายใน url ด้านล่างนี้ (แนะนำเป็นรูปทนาย Phoenix) */
    background: linear-gradient(rgba(0,0,50,0.8), rgba(0,0,0,0.9)), 
                url(data:image/webp;base64,) center/cover no-repeat;
}

/* 3. รูปทนายเมื่อ "ชนะ" คดี (Result WIN) */
#result-screen.bg-win {
    /* ใส่รหัสรูปทนายตอนดีใจใน url ด้านล่างนี้ */
    background: linear-gradient(rgba(0,50,0,0.8), rgba(0,0,0,0.9)), 
                url(data:image/png;base64,) center/cover no-repeat !important;
}

/* 4. รูปทนายเมื่อ "แพ้" คดี (Result LOSE) */
#result-screen.bg-lose {
    /* ใส่รหัสรูปทนายตอนตกใจ/เศร้าใน url ด้านล่างนี้ */
    background: linear-gradient(rgba(50,0,0,0.8), rgba(0,0,0,0.9)), 
                url(data:image/jpeg;base64,) center/cover no-repeat !important;